package com.aicharacter.v3;import java.util.*;
public final class DiaryEngine {private DiaryEngine(){}public static void reflect(WorldState s,long now){List<MemoryEntry> candidates=new ArrayList<>();for(MemoryEntry m:s.memories)if(now-m.time<=48L*3600000&&m.importance>=.38)candidates.add(m);candidates.sort((a,b)->Double.compare(b.retrievalWeight(now),a.retrievalWeight(now)));if(candidates.isEmpty())return;MemoryEntry lead=candidates.get(0);boolean changed=false;String beliefId="";for(Map.Entry<String,BeliefState>e:s.beliefStates.entrySet())if(!e.getValue().history.isEmpty()&&now-e.getValue().history.get(e.getValue().history.size()-1).timestamp<36L*3600000){changed=true;beliefId=e.getKey();break;}if(lead.importance<.52&&!changed&&s.thoughts.isEmpty())return;String text=groundedText(s,lead,changed,beliefId);DiaryEntry d=new DiaryEntry(IdFactory.next("diary"),now,text,s.mood.label(),changed?"belief_reflection":"memory_reflection");for(int i=0;i<Math.min(3,candidates.size());i++)d.sourceMemoryIds.add(candidates.get(i).memoryId);if(changed)d.sourceBeliefIds.add(beliefId);if(lead.location!=null&&!lead.location.isEmpty())d.relatedPlaceIds.add(lead.location);if(lead.hasTag("creature"))d.relatedCreatureIds.add(s.reedling.id);if(s.diary.isEmpty()||!s.diary.get(s.diary.size()-1).sourceMemoryIds.equals(d.sourceMemoryIds))s.diary.add(d);while(s.diary.size()>60)s.diary.remove(0);}
 private static String groundedText(WorldState s,MemoryEntry m,boolean beliefChanged,String beliefId){StringBuilder b=new StringBuilder();if(m.hasTag("absence"))b.append("Mèo đã vắng đủ lâu để mình để ý. ");else if(m.hasTag("creature"))b.append("Mình lại gặp sinh vật nhỏ quen thuộc ở gần hồ. ");else if(m.hasTag("reflect"))b.append("Mình đã có một khoảng yên để nghĩ ở ").append(naturalPlace(m.location)).append(". ");else b.append("Mình vẫn nhớ rõ chuyện này: ").append(m.summary).append(". ");if(beliefChanged)b.append("Có lẽ điều mình tin về ").append("cat_returns".equals(beliefId)?"việc mèo có quay lại":"chuyện đó").append(" đang thay đổi một chút. ");if(s.body.pain>12)b.append("Cơn đau cũng làm mình thận trọng hơn.");return b.toString().trim();}
 private static String naturalPlace(String id){return "bench_lake_01".equals(id)?"chiếc ghế cạnh hồ":"lakeside".equals(id)?"bờ hồ":"một nơi quen thuộc";}}
